<?php require dirname(__DIR__,3).'/includes/bootstrap.php';$token=$_GET['token']??$_POST['token']??'';$valid=null;if($token){$q=$pdo->prepare('SELECT pr.* FROM password_resets pr WHERE pr.token_hash=? AND pr.used_at IS NULL AND pr.expires_at>NOW() ORDER BY pr.id DESC LIMIT 1');$q->execute([hash('sha256',$token)]);$valid=$q->fetch();}if($_SERVER['REQUEST_METHOD']==='POST'&&$valid){verify_csrf();if(strlen($_POST['password']??'')<10||$_POST['password']!==$_POST['confirm'])$error='Use at least 10 characters and match both fields.';else{$pdo->beginTransaction();$pdo->prepare('UPDATE users SET password_hash=?,force_password_change=0 WHERE id=?')->execute([password_hash($_POST['password'],PASSWORD_DEFAULT),$valid['user_id']]);$pdo->prepare('UPDATE password_resets SET used_at=NOW() WHERE id=?')->execute([$valid['id']]);$pdo->commit();flash('success','Password reset. Sign in with your new password.');redirect('auth/manage-admin/login/');}}?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Reset password</title><link rel="stylesheet" href="<?=app_url('assets/css/app.css')?>"></head><body class="auth-page"><main class="auth-card"><span class="eyebrow">ACCOUNT SECURITY</span><h1>Reset password</h1><?php if(!$valid):?><p>This reset link is invalid or expired. Request a fresh secure link.</p><a class="btn primary" href="<?=app_url('auth/manage-admin/forgot-password/')?>">New reset request</a><?php else:?><p>Create a strong password with at least 10 characters.</p><?php if(isset($error)):?><div class="form-alert"><?=e($error)?></div><?php endif;?><form method="post" class="stack"><?=csrf_field()?><input type="hidden" name="token" value="<?=e($token)?>"><label>New Password<input type="password" name="password" minlength="10" required></label><label>Confirm Password<input type="password" name="confirm" minlength="10" required></label><button class="btn primary">Set new password</button></form><?php endif;?></main></body></html>
